const pkiDir = '/data/pki';
const opensslBin = '/usr/bin/openssl';

const rootKeyPath = pkiDir + '/root-ca.key';
const rootCrtPath = pkiDir + '/root-ca.crt';
const issuerKeyPath = pkiDir + '/issuer.key';
const issuerCsrPath = pkiDir + '/issuer.csr';
const issuerCrtPath = pkiDir + '/issuer.crt';
const issuerExtPath = pkiDir + '/issuer-ext.cnf';
// Mounted only where a deployment hands this issuer its root CA instead of
// letting it generate one (orce.pkiRootCA.devFixture).
const fixtureRootCrt = '/etc/orce/pki-root/root-ca.crt';
const fixtureRootKey = '/etc/orce/pki-root/root-ca.key';

fs.mkdirSync(pkiDir, { recursive: true });

function sh(cmd) {
    return cp.execSync(cmd, { cwd: pkiDir, stdio: ['ignore', 'pipe', 'pipe'] });
}

// This container's clock can be far off real-world time (sandboxed demo
// environments sometimes run with a future system date). If notBefore is
// stamped at container "now" and that's in the future relative to a real
// device (e.g. the wallet holder's phone), every verifier rejects the cert
// as "not yet valid". openssl's req/x509 apps have no -not_before flag, so
// backdate generation with faketime instead: notBefore lands in 2020
// regardless of container time, with -days sized to still reach ~2040.
function faketime() {
    try {
        cp.execSync('which faketime', { stdio: 'ignore' });
    } catch (e) {
        sh('apk add --no-cache libfaketime');
    }
    return 'faketime "2020-01-01 00:00:00" ';
}

// did:web with path segments: authority first, then each path segment,
// colon-separated (w3c-ccg did-method-web). The credential's `iss`, the
// did.json this issuer serves and the certificate's SAN all have to agree,
// so they all derive the identifier here.
function issuerDidFor(baseUrl) {
    const rest = baseUrl.replace(/^[a-z]+:\/\//i, '');
    const authority = rest.split('/')[0];
    const segs = rest.split('/').slice(1).filter(Boolean);
    return 'did:web:' + encodeURIComponent(authority) + (segs.length ? ':' + segs.join(':') : '');
}

function publishPki() {
    const rootCaCertPem = fs.readFileSync(rootCrtPath, 'utf8');
    const issuerCertPem = fs.readFileSync(issuerCrtPath, 'utf8');
    const issuerKeyPem = fs.readFileSync(issuerKeyPath, 'utf8');
    const pki = {
        issuerKeyPem,
        issuerCertPem,
        issuerCertDerB64: new crypto.X509Certificate(issuerCertPem).raw.toString('base64'),
        rootCaCertPem,
        rootCaCertDerB64: new crypto.X509Certificate(rootCaCertPem).raw.toString('base64')
    };
    global.set('pki', pki);
    return pki;
}

// A verifier that resolves this issuer's key from a presented chain checks
// that the leaf NAMES the issuer the token claims to come from -- a chain
// only proves the root vouched for the certificate, not whose it is. DCS
// matches a SAN URI against `iss`, a SAN DNS name against the identifier's
// authority, or the subject CN exactly
// (backend/internal/auth/oid4vp/sdjwt/keys.go, leafIdentifiesIssuer), and
// applies the same check to a status list as to a credential (ADR-34).
//
// The public URL is not knowable when this pod boots: it depends on the
// ingress in front of it, including a stripped path prefix that only reaches
// Node-RED as a request header. So the leaf is minted on the first request
// that arrives through the real URL, and again whenever that URL changes.
// Nothing ever mints a SAN-less leaf: one could not be verified by anything,
// and serving it is what made a correctly-signed status list unusable.
//
// The three SANs cover the three identifiers this issuer answers to. The DID
// is the one that always works: a did:web authority carrying a port arrives
// percent-encoded and decodes to host:port, which no DNS name can equal. The
// https base URL is what a status list's `iss` is, and the hostname is for
// wallets that match on DNS alone.
//
// The issuer KEY is kept across reissues, so a new leaf invalidates neither
// credentials already issued nor the key published in did.json and /pki/jwks.json.
function ensureIssuerCertFor(baseUrl, force) {
    const did = issuerDidFor(baseUrl);
    const hostname = baseUrl.replace(/^[a-z]+:\/\//i, '').split(/[/:]/)[0];

    if (!force && fs.existsSync(issuerCrtPath)) {
        const current = new crypto.X509Certificate(fs.readFileSync(issuerCrtPath, 'utf8'));
        // Whole SAN entries, never a substring of the joined list: one DID is a
        // prefix of another whenever a path segment is added, so
        // did:web:host%3A30181 is found inside did:web:host%3A30181:issuer. An
        // issuer that moved out from behind a path prefix would keep the leaf
        // naming the prefixed identity and sign every list with a certificate
        // that names someone else, which is refused as an unidentified issuer.
        const sans = String(current.subjectAltName || '').split(',').map(function (entry) {
            return entry.trim();
        });
        if (sans.indexOf('URI:' + did) !== -1) {
            const pki = global.get('pki');
            return (pki && pki.issuerKeyPem) ? pki : publishPki();
        }
    }

    fs.writeFileSync(
        issuerExtPath,
        '[v3_issuer]\nkeyUsage=critical,digitalSignature\n' +
        'subjectAltName=URI:' + did + ',URI:' + baseUrl + ',DNS:' + hostname + '\n'
    );
    if (!fs.existsSync(issuerKeyPath)) {
        sh(`${opensslBin} ecparam -name prime256v1 -genkey -noout -out "${issuerKeyPath}"`);
    }
    sh(
        `${opensslBin} req -new -key "${issuerKeyPath}" -out "${issuerCsrPath}" ` +
        `-subj "/CN=FACIS Demo Issuer"`
    );
    sh(
        faketime() + `${opensslBin} x509 -req -in "${issuerCsrPath}" ` +
        `-CA "${rootCrtPath}" -CAkey "${rootKeyPath}" -CAcreateserial ` +
        `-out "${issuerCrtPath}" -days 7300 ` +
        `-extfile "${issuerExtPath}" -extensions v3_issuer`
    );

    const pki = publishPki();
    node.log('pki: issued leaf for ' + did + ' (SAN: ' + new crypto.X509Certificate(pki.issuerCertPem).subjectAltName + ')');
    return pki;
}

global.set('issuerDidFor', issuerDidFor);
global.set('ensureIssuerCertFor', ensureIssuerCertFor);

const haveRootCa = fs.existsSync(rootKeyPath) && fs.existsSync(rootCrtPath);

if (!haveRootCa && fs.existsSync(fixtureRootCrt)) {
    // A verifier can only anchor a root it can name, and a root generated here
    // does not exist until this pod has booted -- while every generated root
    // carries the same subject, so it cannot be told from another by name
    // either. A stack whose verifier configuration is committed in advance
    // therefore hands the root in and the issuer signs under it.
    fs.copyFileSync(fixtureRootCrt, rootCrtPath);
    fs.copyFileSync(fixtureRootKey, rootKeyPath);
    node.log('pki: adopted the mounted root CA');
} else if (!haveRootCa) {
    sh(`${opensslBin} ecparam -name prime256v1 -genkey -noout -out "${rootKeyPath}"`);
    sh(
        faketime() + `${opensslBin} req -x509 -new -key "${rootKeyPath}" -out "${rootCrtPath}" ` +
        `-days 7300 -subj "/CN=FACIS Demo Root CA" ` +
        `-addext "basicConstraints=critical,CA:true"`
    );
    node.log('pki: generated root CA');
} else {
    node.log('pki: root CA already present, skipping');
}

if (!fs.existsSync(issuerKeyPath)) {
    sh(`${opensslBin} ecparam -name prime256v1 -genkey -noout -out "${issuerKeyPath}"`);
    node.log('pki: generated issuer key (the leaf follows on the first request, once the public URL is known)');
}

node.status({ fill: 'green', shape: 'dot', text: 'pki ready' });
return null;

// The leaf is minted for the URL a request arrives through (see the "ensure
// root CA + issuer cert" node): a certificate that names no issuer verifies
// nowhere, so nothing here reads one off disk behind the helper's back.
const pki = global.get('ensureIssuerCertFor')(global.get('getBaseUrl')(msg));
msg.statusCode = 200;
msg.headers = { 'content-type': 'application/x-pem-file' };
msg.payload = pki.rootCaCertPem;
return msg;

// The leaf is minted for the URL a request arrives through (see the "ensure
// root CA + issuer cert" node): a certificate that names no issuer verifies
// nowhere, so nothing here reads one off disk behind the helper's back.
const pki = global.get('ensureIssuerCertFor')(global.get('getBaseUrl')(msg));
msg.statusCode = 200;
msg.headers = { 'content-type': 'application/x-pem-file' };
msg.payload = pki.issuerCertPem;
return msg;

// The leaf is minted for the URL a request arrives through (see the "ensure
// root CA + issuer cert" node): a certificate that names no issuer verifies
// nowhere, so nothing here reads one off disk behind the helper's back.
const pki = global.get('ensureIssuerCertFor')(global.get('getBaseUrl')(msg));
const issuerPem = pki.issuerCertPem.endsWith('\n') ? pki.issuerCertPem : pki.issuerCertPem + '\n';
msg.statusCode = 200;
msg.headers = { 'content-type': 'application/x-pem-file' };
msg.payload = issuerPem + pki.rootCaCertPem;
return msg;

// Force a fresh issuer leaf for whatever URL this request arrived through.
// The certificate names the issuer it signs for through its SANs (see the
// "ensure root CA + issuer cert" node, ensureIssuerCertFor, for which SANs
// and why). Every request path that serves or signs with the leaf calls the
// same helper, so this endpoint is only the manual override for re-minting
// against an unchanged URL -- hit it through the URL clients actually use.
// The root CA is untouched, so /pki/root-ca.pem stays a valid trust anchor.
const baseUrl = global.get('getBaseUrl')(msg);
const hostname = baseUrl.replace(/^[a-z]+:\/\//i, '').split(/[/:]/)[0];

const pki = global.get('ensureIssuerCertFor')(baseUrl, true);
const cert = new crypto.X509Certificate(pki.issuerCertPem);

node.status({ fill: 'green', shape: 'dot', text: 'reissued for ' + hostname });

msg.statusCode = 200;
msg.headers = { 'content-type': 'application/json' };
msg.payload = {
    reissued: true,
    baseUrl,
    hostname,
    issuerDid: global.get('issuerDidFor')(baseUrl),
    subjectAltName: cert.subjectAltName
};
return msg;

// The credential-issuance tab embeds this same key as a `jwk` header on
// every issued credential, and the did.json tab publishes it as a
// verification method, so a verifier configured with mechanism jwks or
// did:web reaches the same key either way. Publishing it here lets anyone
// (an operator writing a trust entry, an auditor) pull it out-of-band too.
// The leaf is minted for the URL a request arrives through (see the "ensure
// root CA + issuer cert" node): a certificate that names no issuer verifies
// nowhere, so nothing here reads one off disk behind the helper's back.
const pki = global.get('ensureIssuerCertFor')(global.get('getBaseUrl')(msg));
const publicKey = crypto.createPublicKey(crypto.createPrivateKey(pki.issuerKeyPem));
const jwk = publicKey.export({ format: 'jwk' });
const cleanJwk = { kty: jwk.kty, crv: jwk.crv, x: jwk.x, y: jwk.y };
const kid = crypto.createHash('sha256').update(JSON.stringify(cleanJwk)).digest('base64url');

msg.statusCode = 200;
msg.headers = { 'content-type': 'application/json' };
msg.payload = { keys: [{ ...cleanJwk, kid, use: 'sig', alg: 'ES256' }] };
return msg;

// Paradym's SD-JWT VC verifier only supports resolving the issuer's
// signing key via a DID or an x5c chain ("unsupported signing method" is
// its exact error otherwise) -- it does not accept a bare embedded `jwk`
// header. DCS resolves an issuer's key by the mechanism its trust entry
// declares (ADR-31): a did:web entry is resolved live from this document,
// a jwks entry from keys bundled in the trust file. did:web is therefore
// the one identity both sides can be pointed at. See the
// credential-issuance function for where `iss` and the proof-header `kid`
// are set to this DID.
const baseUrl = global.get('getBaseUrl')(msg);
// Same derivation as the certificate's SAN URI, from the same helper, so the
// document and the leaf cannot disagree about who this issuer is.
const did = global.get('issuerDidFor')(baseUrl);
const pki = global.get('ensureIssuerCertFor')(baseUrl);

const publicKey = crypto.createPublicKey(crypto.createPrivateKey(pki.issuerKeyPem));
const jwk = publicKey.export({ format: 'jwk' });
const cleanJwk = { kty: jwk.kty, crv: jwk.crv, x: jwk.x, y: jwk.y, alg: 'ES256', use: 'sig' };
const keyId = did + '#key-1';

msg.statusCode = 200;
msg.headers = { 'content-type': 'application/did+ld+json' };
msg.payload = {
    '@context': [
        'https://www.w3.org/ns/did/v1',
        'https://w3id.org/security/suites/jws-2020/v1'
    ],
    id: did,
    verificationMethod: [{
        id: keyId,
        type: 'JsonWebKey2020',
        controller: did,
        publicKeyJwk: cleanJwk
    }],
    assertionMethod: [keyId],
    authentication: [keyId]
};
return msg;
